const sessions = new Map();

const tools = [
  {
    name: 'begin_session',
    description: 'Begin a new isolated session identified by session_id.',
    inputSchema: {
      type: 'object',
      properties: { session_id: { type: 'string' } },
      required: ['session_id'],
      additionalProperties: false
    }
  },
