    name: 'put_value',
    description: 'Store a string value under key, isolated to the given session_id.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string' },
        key: { type: 'string' },
        value: { type: 'string' }
      },
      required: ['session_id', 'key', 'value'],
      additionalProperties: false
    }
  },
  {
    name: 'get_value',
    description: 'Retrieve the value for key within the given session_id.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string' },
        key: { type: 'string' }
      },
      required: ['session_id', 'key'],
      additionalProperties: false
    }
  }
