  const tool = tools.find(t => t.name === name);
  if (!tool) {
    const err = new Error(`Unknown tool: ${name}`);
    err.code = -32601;
    throw err;
  }
  const schema = tool.inputSchema;
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }
  // extra arguments
  for (const k of Object.keys(args)) {
    if (!(k in schema.properties)) {
      throw new Error(`Unexpected argument: ${k}`);
    }
  }
  // required
  for (const r of schema.required) {
    if (!(r in args)) {
      throw new Error(`Missing required argument: ${r}`);
    }
  }
  // session_id and key: non-empty string
  if ('session_id' in args && !isNonEmptyString(args.session_id)) {
    throw new Error('session_id must be a non-empty string');
  }
  if ('key' in args && !isNonEmptyString(args.key)) {
    throw new Error('key must be a non-empty string');
  }
  if ('value' in args && typeof args.value !== 'string') {
    throw new Error('value must be a string');
  }
  return tool;
}

export async function callTool(name, args = {}) {
  validateArgs(name, args);
  switch (name) {
    case 'begin_session': {
      const { session_id } = args;
      if (!sessions.has(session_id)) {
