        throw new Error(`session not found: ${session_id}`);
      }
      const store = sessions.get(session_id);
      if (!store.has(key)) {
        throw new Error(`key not found: ${key}`);
      }
      return { content: [{ type: 'text', text: store.get(key) }] };
    }
    default:
      throw new Error(`Unknown tool: ${name}`);
  }
}
